-- A: the rota
CREATE TABLE on_call (shift_id bigint NOT NULL, doctor text NOT NULL,
                      on_call boolean NOT NULL DEFAULT true, PRIMARY KEY (shift_id, doctor));
INSERT INTO on_call VALUES (1201, 'Okafor', true), (1201, 'Lind', true), (1202, 'Ruiz', true);

-- 1. both doctors go off call at REPEATABLE READ
-- A
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM on_call WHERE shift_id = 1201 AND on_call;
-- B
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT count(*) FROM on_call WHERE shift_id = 1201 AND on_call;
-- A: 2 on call, so Okafor may go
UPDATE on_call SET on_call = false WHERE shift_id = 1201 AND doctor = 'Okafor';
-- B: 2 on call, so Lind may go
UPDATE on_call SET on_call = false WHERE shift_id = 1201 AND doctor = 'Lind';
-- A
COMMIT;
-- B
COMMIT;
-- A
SELECT doctor, on_call FROM on_call WHERE shift_id = 1201 ORDER BY doctor;
UPDATE on_call SET on_call = true;

-- 2. lock the on-call rows first, at READ COMMITTED
-- A
BEGIN;
SELECT doctor FROM on_call WHERE shift_id = 1201 AND on_call ORDER BY doctor FOR UPDATE;
-- B (waits)
\timing on
BEGIN;
SELECT doctor FROM on_call WHERE shift_id = 1201 AND on_call ORDER BY doctor FOR UPDATE;
-- A: two rows came back, so Okafor may go
UPDATE on_call SET on_call = false WHERE shift_id = 1201 AND doctor = 'Okafor';
COMMIT;
-- B: one row came back, so Lind must stay
ROLLBACK;
-- A
SELECT doctor, on_call FROM on_call WHERE shift_id = 1201 ORDER BY doctor;

sections.body:
Now book a meeting room. A booking is a row in `room_bookings` whose `during` column is a `tstzrange`, a range of timestamps. Ranges here are half-open: `[12:00,13:00)` includes 12:00 and stops just before 13:00, so a booking from 13:00 doesn't overlap it. `a && b` is true when two ranges overlap. Room 4 is free between 12:00 and 13:00, and the app checks before it inserts:

```sql
BEGIN;
SELECT booking_id FROM room_bookings
WHERE room_id = 4 AND during && tstzrange('2026-12-01 12:00+00', '2026-12-01 13:00+00')
FOR UPDATE;                                      -- 0 rows: the room is free
INSERT INTO room_bookings (room_id, during, booked_by) VALUES (4, ..., 'settlement review');
COMMIT;
```

The `FOR UPDATE` is the doctors' fix, copied here, and it does nothing. A row lock is a mark on a row that exists (lesson 2). The check found no rows, so it marked none. The second booker's check also finds none and also doesn't wait, because neither transaction can see the other's uncommitted insert. Both insert, both commit, and 12:30 to 13:00 is booked twice. The figure shows the timeline.

The new booking is a **phantom**: a row that matches a query's search condition but was written by another transaction after the query ran. In lesson 1 a phantom was a nuisance, a second count in one Read Committed transaction that came out one higher. Here it breaks a rule. Both the check and the write are about a row that doesn't exist yet, so the conflict between the two transactions has nothing to attach to. Repeatable Read doesn't help: a snapshot hides the other booking from your reads, and it doesn't stop the other transaction from inserting it.

The same shape turns up wherever a rule says "no row like this may exist yet":

- a username or an email address that must be unique;
- one payout per merchant per day, or one primary card per account;
- the refunds of a payment, which must not add up to more than the payment, when each refund is a new row;
- a gift card spent twice, when each spend is recorded as a new row.

Each of them checks for absence, then inserts. A row lock can't protect an absence. The next three sections give the conflict something to hold on to.

code.src:
-- A: rooms and their bookings
CREATE TABLE rooms (room_id bigint PRIMARY KEY, name text NOT NULL);
INSERT INTO rooms VALUES (4, 'Ledger'), (7, 'Clearing');
CREATE TABLE room_bookings (booking_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    room_id bigint NOT NULL REFERENCES rooms, during tstzrange NOT NULL, booked_by text NOT NULL);
INSERT INTO room_bookings (room_id, during, booked_by)
VALUES (4, '[2026-12-01 09:00+00, 2026-12-01 10:00+00)', 'risk team');

-- A: is 12:00-13:00 free? Lock whatever is in the way
BEGIN;
SELECT booking_id FROM room_bookings WHERE room_id = 4
  AND during && tstzrange('2026-12-01 12:00+00', '2026-12-01 13:00+00') FOR UPDATE;
-- B: is 12:30-13:30 free?
BEGIN;
SELECT booking_id FROM room_bookings WHERE room_id = 4
  AND during && tstzrange('2026-12-01 12:30+00', '2026-12-01 13:30+00') FOR UPDATE;
-- A: nothing in the way, so book
INSERT INTO room_bookings (room_id, during, booked_by)
VALUES (4, tstzrange('2026-12-01 12:00+00', '2026-12-01 13:00+00'), 'settlement review');
-- B: nothing in the way, so book
INSERT INTO room_bookings (room_id, during, booked_by)
VALUES (4, tstzrange('2026-12-01 12:30+00', '2026-12-01 13:30+00'), 'card ops');
-- A
COMMIT;
-- B
COMMIT;
SELECT booking_id, during, booked_by FROM room_bookings WHERE room_id = 4 ORDER BY lower(during);

sections.body:
If the conflict has no row, give it one. Every booking of room 4 can lock room 4's own row in `rooms` before it checks:

```sql
BEGIN;
SELECT name FROM rooms WHERE room_id = 4 FOR UPDATE;     -- the second booker waits here
SELECT count(*) FROM room_bookings WHERE room_id = 4 AND during && ...;
INSERT ...;
COMMIT;
```

The room's row always exists, so the second booker's lock request waits until the first commits, and its count, a new statement at Read Committed, then sees the first booking. This is **materializing the conflict**: turning a conflict over rows that might exist into a lock on a row that does. When no natural parent row exists, you can create rows for the purpose, say a `room_slots` table with one row per room per 15 minutes for the next six months, which every booking locks before it inserts. Treat that as a last resort. The slot table is concurrency control leaking into the data model, every writer has to remember to lock it, and one forgotten code path brings the double booking back. A parent row is the cheap version: lock the payment before inserting a refund, the merchant before a payout, the account before a card.

Better still, state the rule so the database enforces it. For an exact key that is a UNIQUE constraint: `UNIQUE (merchant_id, payout_day)`, or the course schema's `payment_uid`. For overlapping ranges, PostgreSQL has the **exclusion constraint**, a generalization of UNIQUE: no two rows may make the listed operators all true.

```sql
ALTER TABLE room_bookings ADD CONSTRAINT no_double_booking
    EXCLUDE USING gist (room_id WITH =, during WITH &&);
```

No two rows may have equal `room_id` and overlapping `during`. PostgreSQL checks it through a GiST index. The `btree_gist` extension lets plain `=` on a bigint sit in that index, and the course schema already installs it. PostgreSQL 18 adds temporal keys, `UNIQUE (room_id, during WITHOUT OVERLAPS)`, which the docs say behaves like the same exclusion constraint; the course schema's `merchant_fee_schedules` table uses one.

A constraint holds under concurrency because its check looks at every row in the index, committed or not. In the Try it, B's insert finds A's uncommitted booking, waits for A's transaction, and fails with SQLSTATE 23P01 the moment A commits. There is no check query to get wrong and no code path that can forget it. Use a constraint whenever the rule fits one. The rules that don't fit involve arithmetic across rows: a total, "at least one doctor", a sum of refunds.

code.src:
-- A
DELETE FROM room_bookings WHERE booking_id = 3;
ALTER TABLE room_bookings ADD CONSTRAINT no_double_booking
    EXCLUDE USING gist (room_id WITH =, during WITH &&);
BEGIN;
INSERT INTO room_bookings (room_id, during, booked_by)
VALUES (4, tstzrange('2026-12-01 15:00+00', '2026-12-01 16:00+00'), 'payroll');
-- B (waits)
\timing on
BEGIN;
INSERT INTO room_bookings (room_id, during, booked_by)
VALUES (4, tstzrange('2026-12-01 15:30+00', '2026-12-01 16:30+00'), 'fraud ops');
-- A
COMMIT;
-- B
\echo :SQLSTATE
ROLLBACK;
INSERT INTO room_bookings (room_id, during, booked_by)
VALUES (4, tstzrange('2026-12-01 16:00+00', '2026-12-01 17:00+00'), 'fraud ops');
INSERT INTO room_bookings (room_id, during, booked_by)
VALUES (7, tstzrange('2026-12-01 15:30+00', '2026-12-01 16:30+00'), 'fraud ops');

-- A: is room 4 free from 12:00 to 13:00? (REPEATABLE READ, the default)
START TRANSACTION;
SELECT booking_id, starts_at, ends_at FROM room_bookings
WHERE room_id = 4 AND starts_at < '2026-12-01 13:00' AND ends_at > '2026-12-01 12:00'
FOR UPDATE;

-- B: a booking that overlaps nothing A asked about (waits)
SET innodb_lock_wait_timeout = 5;
START TRANSACTION;
INSERT INTO room_bookings (room_id, starts_at, ends_at, booked_by)
VALUES (4, '2026-12-01 13:30', '2026-12-01 14:00', 'payroll');

-- C: who holds what
SELECT index_name, lock_mode, lock_status, lock_data FROM performance_schema.data_locks
WHERE lock_type = 'RECORD' ORDER BY engine_transaction_id, index_name, lock_data;

-- B, after the timeout
INSERT INTO room_bookings (room_id, starts_at, ends_at, booked_by)
VALUES (4, '2026-12-01 15:30', '2026-12-01 16:00', 'payroll');
INSERT INTO room_bookings (room_id, starts_at, ends_at, booked_by)
VALUES (7, '2026-12-01 12:30', '2026-12-01 13:30', 'card ops');
ROLLBACK;
-- A
ROLLBACK;

-- A
ALTER TABLE room_bookings DROP CONSTRAINT no_double_booking;
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM room_bookings WHERE room_id = 4
  AND during && tstzrange('2026-12-01 13:00+00', '2026-12-01 14:00+00');
-- B
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM room_bookings WHERE room_id = 4
  AND during && tstzrange('2026-12-01 13:30+00', '2026-12-01 14:30+00');
-- A: 0, so book
INSERT INTO room_bookings (room_id, during, booked_by)
VALUES (4, tstzrange('2026-12-01 13:00+00', '2026-12-01 14:00+00'), 'audit');
-- B: 0, so book
INSERT INTO room_bookings (room_id, during, booked_by)
VALUES (4, tstzrange('2026-12-01 13:30+00', '2026-12-01 14:30+00'), 'card ops');
-- A
COMMIT;
-- B
COMMIT;
\echo :SQLSTATE
-- B retries from the start
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM room_bookings WHERE room_id = 4
  AND during && tstzrange('2026-12-01 13:30+00', '2026-12-01 14:30+00');
ROLLBACK;
-- A: clean up this lesson's tables
DROP TABLE room_bookings, rooms, on_call;

