-- 1. a key: let a constraint refuse the duplicate (23505)
ALTER TABLE payouts ADD CONSTRAINT one_payout_per_day UNIQUE (merchant_id, payout_date);

-- 2. no overlap: an exclusion constraint (23P01); needs btree_gist for "=" on bigint
ALTER TABLE room_bookings ADD CONSTRAINT no_double_booking
    EXCLUDE USING gist (room_id WITH =, during WITH &&);
--    PostgreSQL 18: UNIQUE (room_id, during WITHOUT OVERLAPS)

-- 3. the rows exist: lock them before counting (Read Committed)
SELECT doctor FROM on_call WHERE shift_id = :shift AND on_call FOR UPDATE;

-- 4. a sum over rows that don't exist yet: lock the parent row first,
--    or run at SERIALIZABLE and retry the whole transaction on 40001
SELECT 1 FROM merchants WHERE merchant_id = :merchant FOR UPDATE;

-- Why not FOR UPDATE in (2): it locks the rows the check returns. A free
-- slot returns none, so it locks none, and a concurrent insert does not wait.
